with target as(select * from public.works where id=any(array[5029,5037,5164,5823,5856,5943,5970,6073,6204,6352]::bigint[]) or open_library_id=any(array['OL2271657W','OL472540W','OL108947W','OL1322647W','OL9302808W','OL20851120W','OL470778W','OL21145645W','OL19740695W','OL21003707W']::text[]) or regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['uilenroepen','owlsdocry','hetlisterdalemysterie','thelisterdalemystery','hetpadvandelichtwerker','thelightworkersway','deetruskischeglimlach','lasonrisaetrusca','dekantlezer','thelacereader','eersteleven','firstlife','bovenwindsehoogten','lamigrationdescoeurs','oogvandestorm','wildfire','west','inverleiding','temptation']::text[]) or id in(select work_id from public.catalog_work_title_aliases where regexp_replace(lower(normalize(title,NFD)),'[^a-z0-9]','','g')=any(array['uilenroepen','owlsdocry','hetlisterdalemysterie','thelisterdalemystery','hetpadvandelichtwerker','thelightworkersway','deetruskischeglimlach','lasonrisaetrusca','dekantlezer','thelacereader','eersteleven','firstlife','bovenwindsehoogten','lamigrationdescoeurs','oogvandestorm','wildfire','west','inverleiding','temptation']::text[]))),a as(select * from public.authors where id in(select author_id from target) or open_library_id=any(array['OL296656A','OL27695A','OL29542A','OL134763A','OL3353071A','OL3481861A','OL27460A','OL2705476A','OL7535167A','OL2621921A']::text[]) or regexp_replace(lower(normalize(name,NFD)),'[^a-z0-9]','','g')=any(array['janetframe','framejanet','agathachristie','yingajiashakelisididiaokeliyi','achristie','agathacmallowan','doreenvirtue','doreendrvirtue','doreenvirtuephd','joseluissampedro','brunoniabarry','genashowalter','maryseconde','mconde','ilonaandrews','gordonilonaandrews','houseandrews','carysdavies','douglaskennedy','kennedydouglas']::text[])),e as(select * from public.editions where work_id in(select id from target) or open_library_edition_id=any(array['OL61625761M','OL61374863M','OL46531802M','OL35726073M','OL47857427M','OL46537272M','OL47227900M','OL62458019M','OL60166729M','OL33334364M']::text[]) or regexp_replace(coalesce(isbn_13,''),'[-[:space:]]','','g')=any(array['9789052264639','9789048823192','9789022559512','9789074622585','9789023457343','9789402723403','9789062654598','9789062221684','9789029093231','9789022548257']::text[])) select jsonb_build_object('project','qvplwejffhjvxaypmjut','checked_at',clock_timestamp(),'works',coalesce((select jsonb_agg(to_jsonb(t) order by id) from target t),'[]'),'authors',coalesce((select jsonb_agg(to_jsonb(t) order by id) from a t),'[]'),'author_corpora',coalesce((select jsonb_agg(to_jsonb(t) order by id) from public.works t where author_id in(select id from a)),'[]'),'editions',coalesce((select jsonb_agg(to_jsonb(t) order by id) from e t),'[]'),'metadata',coalesce((select jsonb_agg(to_jsonb(t) order by edition_id) from public.catalog_edition_metadata t where edition_id in(select id from e)),'[]'),'descriptions',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,language) from public.catalog_work_descriptions t where work_id in(select id from target)),'[]'),'aliases',coalesce((select jsonb_agg(to_jsonb(t) order by work_id,title) from public.catalog_work_title_aliases t where work_id in(select id from target)),'[]')) as snapshot;
